import math

def generate_candidates(limit=100):
    """Generates pairs (x, y) with x < y, calculates m = x^2 + y^2,
    and filters them based on gcd(x, y) == 1 (assuming this is the necessary condition)."""
    candidates = []
    for x in range(1, limit):
        for y in range(x + 1, limit):
            if math.gcd(x, y) == 1:
                m = x**2 + y**2
                candidates.append(m)

    candidates.sort()
    return candidates

all_candidates = generate_candidates(limit=100)

if len(all_candidates) >= 20:
    twentieth_smallest = all_candidates[19]
    print(f"The 20th smallest candidate good number is: {twentieth_smallest}")
else:
    print("Not enough candidates found.")

